IF 64-Bit Mode
    THEN
         #UD;
    ELSE
         IF ((AL AND 0FH) > 9) or (AF = 1)
               THEN
                   AX := AX + 106H;
                   AF := 1;
                   CF := 1;
               ELSE
                   AF := 0;
                   CF := 0;
         FI;
         AL := AL AND 0FH;
FI;

IF 64-Bit Mode
    THEN
         #UD;
    ELSE
         tempAL := AL;
         tempAH := AH;
         AL := (tempAL + (tempAH ∗ imm8)) AND FFH;
         (* imm8 is set to 0AH for the AAD mnemonic.*)
         AH := 0;
FI;
The immediate value (imm8) is taken from the second byte of the instruction.

IF 64-Bit Mode
    THEN
         #UD;
    ELSE
         tempAL := AL;
         AH := tempAL / imm8; (* imm8 is set to 0AH for the AAM mnemonic *)
         AL := tempAL MOD imm8;
FI;
The immediate value (imm8) is taken from the second byte of the instruction.

IF 64-bit mode
    THEN
         #UD;
    ELSE
         IF ((AL AND 0FH) > 9) or (AF = 1)
               THEN
                   AX := AX – 6;
                   AH := AH – 1;
                   AF := 1;
                   CF := 1;
                   AL := AL AND 0FH;
               ELSE
                   CF := 0;
                   AF := 0;
                   AL := AL AND 0FH;
         FI;
FI;

