operation:
(* Accumulator = AL, AX, EAX, or RAX depending on whether a byte, word, doubleword, or quadword comparison is being performed *)
TEMP := DEST
IF accumulator = TEMP
    THEN
        ZF := 1;
        DEST := SRC;
    ELSE
        ZF := 0;
        accumulator := TEMP;
        DEST := TEMP;
FI;

IF (64-Bit Mode and OperandSize = 64)
    THEN
         TEMP128 := DEST
         IF (RDX:RAX = TEMP128)
              THEN
                  ZF := 1;
                  DEST := RCX:RBX;
              ELSE
                  ZF := 0;
                  RDX:RAX := TEMP128;
                  DEST := TEMP128;
                  FI;
         FI
    ELSE
         TEMP64 := DEST;
         IF (EDX:EAX = TEMP64)
              THEN
                  ZF := 1;
                  DEST := ECX:EBX;
              ELSE
                  ZF := 0;
                  EDX:EAX := TEMP64;
                  DEST := TEMP64;
                  FI;
         FI;
FI;

COMISD (All Versions)
RESULT :=OrderedCompare(DEST[63:0] <> SRC[63:0]) {
(* Set EFLAGS *) CASE (RESULT) OF
    UNORDERED: ZF,PF,CF := 111;
    GREATER_THAN: ZF,PF,CF := 000;
    LESS_THAN: ZF,PF,CF := 001;
    EQUAL: ZF,PF,CF := 100;
ESAC;
OF, AF, SF := 0; }

COMISS (All Versions)
RESULT :=OrderedCompare(DEST[31:0] <> SRC[31:0]) {
(* Set EFLAGS *) CASE (RESULT) OF
    UNORDERED: ZF,PF,CF := 111;
    GREATER_THAN: ZF,PF,CF := 000;
    LESS_THAN: ZF,PF,CF := 001;
