    THEN
        // set newCS to standard values used ring 3 in compatibility mode
             newCS.selector := tempCS[15:0];
             newCS.base := 0;
             newCS.limit := FFFFFH;
             newCS.type := 11;
             newCS.S := 1;
             newCS.DPL := 3;
             newCS.P := 1;
             newCS.L := 0;
             newCS.D := 1;
             newCS.G := 1;
             newCS.unusable := 0;
        // set newSS to standard values for ring 3
             newSS.selector := tempSS[15:0];
             newSS.base := 0;
             newSS.limit := FFFFFH;
             newSS.type := 3;
             newSS.S := 1;
             newSS.DPL := 3;
             newSS.P := 1;
             newSS.B := 1;
             newSS.G := 1;
             newSS.unusable := 0;
