RFLAGS := newRFLAGS;                             // ERETU can set RFLAGS.RF to 1
RSP := newRSP;                                   // load all 64 bits regardless of new mode
CS := newCS;                                     // selector and descriptor
SS := newSS;                                     // selector and descriptor
