FI;

IF Instruction = FIADD
     THEN
         DEST := DEST + ConvertToDoubleExtendedPrecisionFP(SRC);
     ELSE (* Source operand is floating-point value *)
         DEST := DEST + SRC;
FI;
IF Instruction = FADDP
     THEN
         PopRegisterStack;
FI;

IF condition TRUE
    THEN ST(0) := ST(i);
FI;

CASE (relation of operands) OF
   ST > SRC:          C3, C2, C0 := 000;
   ST < SRC:          C3, C2, C0 := 001;
   ST = SRC:          C3, C2, C0 := 100;
ESAC;
