    THEN TOP := 7;
    ELSE TOP := TOP – 1;
FI;

IF SRC = 0
    THEN
        #Z;
    ELSE
        IF Instruction is FIDIV
              THEN
                  DEST := DEST / ConvertToDoubleExtendedPrecisionFP(SRC);
              ELSE (* Source operand is floating-point value *)
                  DEST := DEST / SRC;
        FI;
FI;
IF Instruction = FDIVP
     THEN
         PopRegisterStack;
FI;

