FI;

IF TOP = 7
    THEN TOP := 0;
    ELSE TOP := TOP + 1;
FI;

FPUControlWord := 037FH;
FPUStatusWord := 0;
FPUTagWord := FFFFH;
FPUDataPointer := 0;
FPUInstructionPointer := 0;
FPULastInstructionOpcode := 0;

DEST := Integer(ST(0));
IF Instruction = FISTP
     THEN
         PopRegisterStack;
FI;

IF SRC is ST(i)
    THEN
         temp := ST(i);
FI;
TOP := TOP − 1;
IF SRC is memory-operand
    THEN
         ST(0) := ConvertToDoubleExtendedPrecisionFP(SRC);
    ELSE (* SRC is ST(i) *)
