Non-64-bit Mode:
IF (Byte transfer)
    THEN IF DF = 0
         THEN (E)DI := (E)DI + 1;
         ELSE (E)DI := (E)DI – 1; FI;
    ELSE IF (Word transfer)
         THEN IF DF = 0
             THEN (E)DI := (E)DI + 2;
             ELSE (E)DI := (E)DI – 2; FI;
         ELSE (* Doubleword transfer *)
             THEN IF DF = 0
                   THEN (E)DI := (E)DI + 4;
                   ELSE (E)DI := (E)DI – 4; FI;
