operation:
IF 64-bit Mode
    THEN #UD
FI;
IF OperandSize = 32 (* PUSHAD instruction *)
    THEN
         Temp := (ESP);
         Push(EAX);
         Push(ECX);
         Push(EDX);
         Push(EBX);
         Push(Temp);
         Push(EBP);
         Push(ESI);
         Push(EDI);
    ELSE (* OperandSize = 16, PUSHA instruction *)
         Temp := (SP);
         Push(AX);
         Push(CX);
         Push(DX);
         Push(BX);
         Push(Temp);

        Push(BP);
        Push(SI);
        Push(DI);
FI;

(* RCL and RCR Instructions *)
SIZE := OperandSize;
CASE (determine count) OF
    SIZE := 8:   tempCOUNT := (COUNT AND 1FH) MOD 9;
    SIZE := 16:  tempCOUNT := (COUNT AND 1FH) MOD 17;
    SIZE := 32:  tempCOUNT := COUNT AND 1FH;
    SIZE := 64:  tempCOUNT := COUNT AND 3FH;
ESAC;
IF OperandSize = 64
    THEN COUNTMASK = 3FH;
    ELSE COUNTMASK = 1FH;
FI;

(* RCL Instruction Operation *)
tempDEST := DEST;
WHILE (tempCOUNT ≠ 0)
    DO
        tempCF := MSB(tempDEST);
        tempDEST := (tempDEST ∗ 2) + CF;
        CF := tempCF;
        tempCOUNT := tempCOUNT – 1;
    OD;
ELIHW;
IF (COUNT & COUNTMASK) = 1
    THEN OF := MSB(tempDEST) XOR CF;
    ELSE OF is undefined;
FI;
DEST := tempDEST;

(* RCR Instruction Operation *)
tempDEST := DEST;
IF (COUNT & COUNTMASK) = 1
    THEN OF := MSB(tempDEST) XOR CF;
    ELSE OF is undefined;
FI;
WHILE (tempCOUNT ≠ 0)
    DO
        tempCF := LSB(SRC);
        tempDEST := (tempDEST / 2) + (CF * 2SIZE);
        CF := tempCF;
        tempCOUNT := tempCOUNT – 1;
    OD;
DEST := tempDEST;

(* ROL Instruction Operation *)
tempCOUNT := (COUNT & COUNTMASK) MOD SIZE
tempDEST := DEST;
WHILE (tempCOUNT ≠ 0)
    DO
        tempCF := MSB(tempDEST);
        tempDEST := (tempDEST ∗ 2) + tempCF;
        tempCOUNT := tempCOUNT – 1;
    OD;
ELIHW;
IF (COUNT & COUNTMASK) ≠ 0
    THEN CF := LSB(tempDEST);
FI;
IF (COUNT & COUNTMASK) = 1
    THEN OF := MSB(tempDEST) XOR CF;
    ELSE OF is undefined;
FI;
DEST := tempDEST;

(* ROR Instruction Operation *)
tempCOUNT := (COUNT & COUNTMASK) MOD SIZE
tempDEST := DEST;
WHILE (tempCOUNT ≠ 0)
    DO
        tempCF := LSB(SRC);
        tempDEST := (tempDEST / 2) + (tempCF ∗ 2SIZE);
        tempCOUNT := tempCOUNT – 1;
    OD;
ELIHW;
IF (COUNT & COUNTMASK) ≠ 0
    THEN CF := MSB(tempDEST);
FI;
IF (COUNT & COUNTMASK) = 1
    THEN OF := MSB(tempDEST) XOR MSB − 1(tempDEST);
    ELSE OF is undefined;
FI;
DEST := tempDEST;

