Non-64-bit Mode:
IF (Byte store)
    THEN
         DEST := AL;
              THEN IF DF = 0
                  THEN (E)DI := (E)DI + 1;
                  ELSE (E)DI := (E)DI – 1;
              FI;
    ELSE IF (Word store)
         THEN
              DEST := AX;
                  THEN IF DF = 0
                       THEN (E)DI := (E)DI + 2;
                       ELSE (E)DI := (E)DI – 2;
                  FI;
         FI;
    ELSE IF (Doubleword store)
         THEN
              DEST := EAX;
                  THEN IF DF = 0
                       THEN (E)DI := (E)DI + 4;
                       ELSE (E)DI := (E)DI – 4;
                  FI;
         FI;
FI;

64-bit Mode:
IF (Byte store)
    THEN
         DEST := AL;
              THEN IF DF = 0
                  THEN (R|E)DI := (R|E)DI + 1;
                  ELSE (R|E)DI := (R|E)DI – 1;
              FI;
    ELSE IF (Word store)
         THEN
              DEST := AX;
                  THEN IF DF = 0
                       THEN (R|E)DI := (R|E)DI + 2;
                       ELSE (R|E)DI := (R|E)DI – 2;
                  FI;
         FI;
    ELSE IF (Doubleword store)

          THEN
                DEST := EAX;
                    THEN IF DF = 0
                         THEN (R|E)DI := (R|E)DI + 4;
                         ELSE (R|E)DI := (R|E)DI – 4;
                    FI;
          FI;
      ELSE IF (Quadword store using REX.W )
          THEN
                DEST := RAX;
                    THEN IF DF = 0
                         THEN (R|E)DI := (R|E)DI + 8;
                         ELSE (R|E)DI := (R|E)DI – 8;
                    FI;
          FI;
FI;

STTILECFG mem
if TILES_CONFIGURED == 0:
    //write 64 bytes of zeros at mem pointer
    buf[0..63] := 0
    write_memory(mem, 64, buf)
else:
    buf.byte[0] := tilecfg.palette_id
    buf.byte[1] := tilecfg.start_row
    buf.byte[2..15] := 0

   p := 16
   for n in 0 ... palette_table[tilecfg.palette_id].max_names-1:
         buf.word[p/2] := tilecfg.t[n].colsb
         p := p + 2
   if p < 47:
         buf.byte[p..47] := 0
   p := 48
   for n in 0 ... palette_table[tilecfg.palette_id].max_names-1:
         buf.byte[p++] := tilecfg.t[n].rows
   if p < 63:
         buf.byte[p..63] := 0

   write_memory(mem, 64, buf)

