operation:
CASE (COMPARISON PREDICATE) OF
   0: OP := EQ;
   1: OP := LT;
   2: OP := LE;
   3: OP := FALSE;
   4: OP := NEQ;
   5: OP := NLT;
   6: OP := NLE;
   7: OP := TRUE;
ESAC;

VPCMPB (EVEX encoded versions)
(KL, VL) = (16, 128), (32, 256), (64, 512)
FOR j := 0 TO KL-1
    i := j * 8
    IF k2[j] OR *no writemask*
           THEN
               CMP := SRC1[i+7:i] OP SRC2[i+7:i];
               IF CMP = TRUE
                    THEN DEST[j] := 1;
                    ELSE DEST[j] := 0; FI;
           ELSE     DEST[j] = 0                 ; zeroing-masking onlyFI;
    FI;
ENDFOR
DEST[MAX_KL-1:KL] := 0

