           Temp2[63:0] := DEST[i+63:i] + ZeroExtend64(temp128[103:52]) ;
           DEST[i+63:i] := Temp2[63:0];
    ELSE
           IF *zeroing-masking* THEN
                DEST[i+63:i] := 0;
           ELSE *merge-masking*
                DEST[i+63:i] is unchanged;
           FI;
    FI;
ENDFOR
